17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
64	     * at least one dot and no whitespace on either side.
65	     */
66	    private static final Pattern EMAIL_PATTERN =
67	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        validateRequiredFields(ownerFieldsDto);
116	        normalizeTelephone(ownerFieldsDto);
117	        rejectDuplicateTelephone(ownerFieldsDto);
118	        normalizeEmail(ownerFieldsDto);
119	        defaultRegistrationDate(ownerFieldsDto);
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        assignCustomerCode(owner);
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        currentOwner.setAddress(ownerFieldsDto.getAddress());
138	        currentOwner.setCity(ownerFieldsDto.getCity());
139	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
140	        currentOwner.setLastName(ownerFieldsDto.getLastName());
141	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
142	        normalizeEmail(ownerFieldsDto);
143	        currentOwner.setEmail(ownerFieldsDto.getEmail());
144	        this.clinicService.saveOwner(currentOwner);
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Transactional
150	    @Override
151	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        this.clinicService.deleteOwner(owner);
157	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Pet pet = petMapper.toPet(petFieldsDto);
169	        owner.setId(ownerId);
170	        pet.setOwner(owner);
171	        pet.getType().setName(null);
172	        this.clinicService.savePet(pet);
173	        PetDto petDto = petMapper.toPetDto(pet);
174	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
175	            .buildAndExpand(pet.getId()).toUri());
176	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
182	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
183	        if (currentOwner != null) {
184	            Pet currentPet = this.clinicService.findPetById(petId);
185	            if (currentPet != null) {
186	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
187	                currentPet.setName(petFieldsDto.getName());
188	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
189	                this.clinicService.savePet(currentPet);
190	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	            }
192	        }
193	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
199	        HttpHeaders headers = new HttpHeaders();
200	        Visit visit = visitMapper.toVisit(visitFieldsDto);
201	        Pet pet = new Pet();
202	        pet.setId(petId);
203	        visit.setPet(pet);
204	        this.clinicService.saveVisit(visit);
205	        VisitDto visitDto = visitMapper.toVisitDto(visit);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
207	            .buildAndExpand(visit.getId()).toUri());
208	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
209	    }
210	
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner != null) {
217	            Pet pet = owner.getPet(petId);
218	            if (pet != null) {
219	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
220	            }
221	        }
222	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	    }
224	
225	    /**
226	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
227	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
228	     * does not catch). The names of all offending fields are collected so the caller receives a
229	     * 400 response whose {@code errors} array lists each one.
230	     */
231	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
232	        List<String> missingFields = new ArrayList<>();
233	        if (isBlank(ownerFieldsDto.getFirstName())) {
234	            missingFields.add("firstName");
235	        }
236	        if (isBlank(ownerFieldsDto.getLastName())) {
237	            missingFields.add("lastName");
238	        }
239	        if (isBlank(ownerFieldsDto.getAddress())) {
240	            missingFields.add("address");
241	        }
242	        if (isBlank(ownerFieldsDto.getCity())) {
243	            missingFields.add("city");
244	        }
245	        if (isBlank(ownerFieldsDto.getTelephone())) {
246	            missingFields.add("telephone");
247	        }
248	        if (!missingFields.isEmpty()) {
249	            throw new InvalidOwnerFieldsException(missingFields);
250	        }
251	    }
252	
253	    private static boolean isBlank(String value) {
254	        return value == null || value.trim().isEmpty();
255	    }
256	
257	    /**
258	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
259	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
260	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
261	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
262	     * string is written back onto the request so it is what gets stored and returned. Any value that
263	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
264	     * names {@code telephone}.
265	     */
266	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
267	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
268	    }
269	
270	    /**
271	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
272	     * (400) naming {@code telephone} when it cannot form a valid number.
273	     */
274	    private static String toE164(String telephone) {
275	        if (telephone == null) {
276	            throw new InvalidOwnerFieldsException(List.of("telephone"));
277	        }
278	        boolean hasCountryCode = telephone.trim().startsWith("+");
279	        String digits = telephone.replaceAll("\\D", "");
280	        String national;
281	        if (hasCountryCode) {
282	            national = digits;
283	        } else {
284	            if (digits.startsWith("0")) {
285	                digits = digits.substring(1);
286	            }
287	            national = "61" + digits;
288	        }
289	        if (!national.matches("[0-9]{8,15}")) {
290	            throw new InvalidOwnerFieldsException(List.of("telephone"));
291	        }
292	        return "+" + national;
293	    }
294	
295	    /**
296	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
297	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
298	     * each existing owner's stored telephone is converted the same way before comparison so numbers
299	     * that only differ in formatting still collide. A match results in a 409 response naming
300	     * {@code telephone}.
301	     */
302	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
303	        String telephone = ownerFieldsDto.getTelephone();
304	        for (Owner existing : this.clinicService.findAllOwners()) {
305	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
306	                throw new DuplicateOwnerTelephoneException(telephone);
307	            }
308	        }
309	    }
310	
311	    /**
312	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
313	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
314	     */
315	    private static String normalizeExisting(String telephone) {
316	        try {
317	            return toE164(telephone);
318	        } catch (InvalidOwnerFieldsException ex) {
319	            return null;
320	        }
321	    }
322	
323	    /**
324	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
325	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
326	     * written back onto the request so that is what gets stored and returned. A present but invalid
327	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
328	     */
329	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
330	        String email = ownerFieldsDto.getEmail();
331	        if (email == null) {
332	            return;
333	        }
334	        String trimmed = email.trim();
335	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
336	            throw new InvalidOwnerFieldsException(List.of("email"));
337	        }
338	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
339	    }
340	
341	    /**
342	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
343	     * it is set to the server's current date so every owner is persisted with a registration date;
344	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
345	     * {@code YYYY-MM-DD} format.
346	     */
347	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
348	        if (ownerFieldsDto.getRegistrationDate() == null) {
349	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
350	        }
351	    }
352	
353	    /**
354	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
355	     * {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN} is a
356	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
357	     * (e.g. {@code 'SMI-0007'}).
358	     */
359	    private void assignCustomerCode(Owner owner) {
360	        String lastName = owner.getLastName();
361	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
362	        int sequence = this.clinicService.findAllOwners().size() + 1;
363	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
364	    }
365	}
